import java.util.*;

class Solution {

    public int[][] merge(int[][] intervals) {

        // If there is only one interval, no merging is needed.
        if (intervals.length <= 1) {
            return intervals;
        }

        // Step 1: Sort intervals based on the start value.
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Step 2: Store merged intervals.
        List<int[]> ans = new ArrayList<>();

        // Step 3: Add the first interval.
        ans.add(intervals[0]);

        // Step 4: Traverse remaining intervals.
        for (int i = 1; i < intervals.length; i++) {

            // Get the last merged interval.
            int[] last = ans.get(ans.size() - 1);

            // If intervals overlap, merge them.
            if (intervals[i][0] <= last[1]) {
                last[1] = Math.max(last[1], intervals[i][1]);
            }

            // Otherwise, add the current interval.
            else {
                ans.add(intervals[i]);
            }
        }

        // Step 5: Convert ArrayList<int[]> to int[][].
        return ans.toArray(new int[ans.size()][]);
    }
}

