        static ArrayList<Integer>  findTheLeader(int arr[] , int n) {
                ArrayList<Integer> list = new ArrayList<>();

                int maxFromRight = arr[n-1];
                list.add(maxFromRight);
                for (int i = n-2; i >= 0; i--) {
                        if(maxFromRight < arr[i]) {
                                maxFromRight = arr[i];
                                list.add(maxFromRight);
                        }
                }
