public class Main {

    static ListNode deleteMiddle(ListNode head) {

        // Only one node
        if (head == null || head.next == null) {
            return null;
        }

        ListNode slow = head;
        ListNode fast = head;
        ListNode prev = null;

        while (fast != null && fast.next != null) {

            prev = slow;
            slow = slow.next;
            fast = fast.next.next;
        }

        // Delete middle
        prev.next = slow.next;

        return head;
    }
}

