        int[] ans = new int[n];

        Stack<Integer> st = new Stack<>();

        for (int i = n - 1; i >= 0; i--) {
            // 3  check the condition
            while (!st.isEmpty() && st.peek() <= arr[i]) {
                st.pop();
            }

            // First check the stack
            ans[i] = st.isEmpty() ? -1 : st.peek();
            // then add
            st.push(arr[i]);
        }

        return ans;
    }

