class Main {
    static int calPoints(String[] ops) {
        Stack<Integer> st = new Stack<>();
        for (String op : ops) {

            if (op.equals("+")) {

                int first = st.pop();
                int second = st.peek();

                st.push(first);

                st.push(first + second);
            }
            else if (op.equals("D")) {

                st.push(2 * st.peek());
            }
            else if (op.equals("C")) {
                st.pop();
            }
            else {

                st.push(Integer.parseInt(op));
            }
        }

        int sum = 0;

        while (!st.isEmpty()) {
            sum += st.pop();
        }
        return sum;
    }

    public static void main(String[] args) {
        String[] ops = {"5","2","C","D","+"};

        System.out.println(calPoints(ops));
    }
}

