class Main {

    static boolean isValid(String s) {

        Stack<Character> st = new Stack<>();

        for (char ch : s.toCharArray()) {

            if (ch == '(' || ch == '[' || ch == '{') {
                st.push(ch);
                // it adds  ( , [ , { first and then closing side 
            } 
            else {

            // If there where no ( , [ , } added in stack that means false  if empty means 
                if (st.isEmpty()) {
                    return false;
                }

                char top = st.pop(); // ([{ if this is the order than at last top will be { , popping top = { ,

                if (ch == ')' && top != '(') {
                    return false;
                }

                if (ch == ']' && top != '[') {
                    return false;
                }

                if (ch == '}' && top != '{') {
                    return false;
                }
            }
        }

        return st.isEmpty();
    }

